import 'package:flutter/material.dart'; import 'models/models.dart'; import 'providers/app_state.dart'; import 'screens/dashboard_screen.dart'; import 'screens/tasks_screen.dart'; import 'screens/detail_screen.dart'; import 'screens/projects_screen.dart'; import 'screens/milestones_screen.dart'; import 'screens/settings_screen.dart'; import 'theme/app_theme.dart'; import 'utils/demo_data.dart'; import 'services/notification_service.dart';
Future<void> main() async {WidgetsFlutterBinding.ensureInitialized();final state=await AppState.create(demoWorkspace());await NotificationService().init();runApp(TaskManagerApp(state));}
class TaskManagerApp extends StatelessWidget{final AppState state;const TaskManagerApp(this.state,{super.key});@override Widget build(BuildContext c)=>AnimatedBuilder(animation:state,builder:(c,_){return MaterialApp(debugShowCheckedModeBanner:false,title:'Task Manager',theme:AppTheme.light(state.accent),darkTheme:AppTheme.dark(state.accent),themeMode:state.themeMode,home:HomeShell(state:state));});}
class HomeShell extends StatefulWidget{final AppState state;const HomeShell({super.key,required this.state});@override State<HomeShell> createState()=>_HomeShellState();}
class _HomeShellState extends State<HomeShell>{Task? detail;@override Widget build(BuildContext c){final wide=MediaQuery.sizeOf(c).width>=900;Widget body=detail!=null?DetailScreen(state:widget.state,task:detail!):switch(widget.state.page){0=>DashboardScreen(state:widget.state,openTask:(t)=>setState(()=>detail=t)),1=>TasksScreen(state:widget.state,openTask:(t)=>setState(()=>detail=t)),2=>ProjectsScreen(state:widget.state),3=>const SizedBox.shrink(),4=>MilestonesScreen(state:widget.state),5=>SettingsScreen(state:widget.state),_=>DashboardScreen(state:widget.state,openTask:(t)=>setState(()=>detail=t))};final items=[(Icons.dashboard,'Overview'),(Icons.checklist,'Tasks'),(Icons.view_kanban,'Projects'),(Icons.label,'Labels'),(Icons.flag,'Milestones'),(Icons.settings,'Settings')];return Scaffold(appBar:AppBar(title:Row(children:[Container(width:28,height:28,decoration:BoxDecoration(color:widget.state.accent,borderRadius:BorderRadius.circular(6)),child:const Icon(Icons.check,color:Colors.white,size:18)),const SizedBox(width:10),const Text('Task Manager',style:TextStyle(fontWeight:FontWeight.w700))]),actions:[IconButton(onPressed:(){},icon:const Icon(Icons.search)),IconButton(onPressed:(){},icon:const Icon(Icons.notifications_none)),const SizedBox(width:8)]),drawer:wide?null:Drawer(child:SafeArea(child:_nav(items))),body:wide?Row(children:[SizedBox(width:250,child:_nav(items)),const VerticalDivider(width:1),Expanded(child:body)]):body,bottomNavigationBar:wide?null:NavigationBar(selectedIndex:widget.state.page.clamp(0,4),onDestinationSelected:(i)=>setState(()=>widget.state.setPage(i)),destinations:items.take(5).map((x)=>NavigationDestination(icon:Icon(x.$1),label:x.$2)).toList()));}
Widget _nav(List<(IconData,String)> items)=>ListView(padding:const EdgeInsets.all(12),children:[const Padding(padding:EdgeInsets.all(12),child:Text('WORKSPACE',style:TextStyle(fontSize:11,fontWeight:FontWeight.bold)),),...items.asMap().entries.map((e)=>ListTile(selected:widget.state.page==e.key,leading:Icon(e.value.$1),title:Text(e.value.$2),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(6)),onTap:(){setState(()=>widget.state.setPage(e.key));if(MediaQuery.sizeOf(context).width<900)Navigator.pop(context);})),const Divider(),const ListTile(leading:Icon(Icons.help_outline),title:Text('Help & feedback'))]);}
